// Round-4 finding R4-01. Regenerated automatically before every dev/build
// run (see package.json's "predev"/"prebuild") -- do not edit lib/build-info.ts
// by hand, it's overwritten every time.
//
// Records which migration this specific build of the application code
// expects the database schema to already have applied, so
// /api/health can report "application/database compatibility" without
// needing a live database connection at request time: the deployed code's
// own expectation is baked in at build time, not queried per-request.
import { readdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const dirname = path.dirname(fileURLToPath(import.meta.url));
const migrationsDir = path.resolve(dirname, "../supabase/migrations");
const files = readdirSync(migrationsDir)
  .filter((f) => f.endsWith(".sql"))
  .sort();
const latest = files.at(-1) ?? null;

const outPath = path.resolve(dirname, "../lib/build-info.ts");
writeFileSync(
  outPath,
  `// Auto-generated by scripts/generate-build-info.mjs -- do not edit by hand.
// Regenerated on every "npm run dev"/"npm run build" (see package.json).
export const LATEST_MIGRATION: string | null = ${JSON.stringify(latest)};
export const MIGRATION_COUNT: number = ${files.length};
`,
);

console.log(`generate-build-info: LATEST_MIGRATION=${latest} (${files.length} total)`);
